import { useState } from 'react';
import Navbar from '../components/Navbar';
import TransactionForm from '../components/TransactionForm';
import TransactionList from '../components/TransactionList';
import SummaryCard from '../components/SummaryCard';
import InvestmentForm from '../components/InvestmentForm';
import InvestmentList from '../components/InvestmentList';
import Tabs from '../components/Tabs';
import styles from './Dashboard.module.css';

const Dashboard = () => {
  const [transactions, setTransactions] = useState([]); // Transacciones normales
  const [investments, setInvestments] = useState([]); // Inversiones
  const [activeTab, setActiveTab] = useState(0);

  // Calcular totalIncome, totalExpenses y balance
  const totalIncome = transactions
    .filter((t) => t.type === 'income')
    .reduce((sum, t) => sum + t.amount, 0);

  const totalExpenses = transactions
    .filter((t) => t.type === 'expense')
    .reduce((sum, t) => sum + t.amount, 0);

  // Calcular ingresos y gastos de las inversiones
  const investmentIncome = investments.reduce((sum, inv) => sum + inv.salePrice, 0);
  const investmentExpenses = investments.reduce((sum, inv) => sum + inv.initialCost, 0);

  // Totales incluyendo inversiones
  const totalIncomeWithInvestments = totalIncome + investmentIncome;
  const totalExpensesWithInvestments = totalExpenses + investmentExpenses;
  const balance = totalIncomeWithInvestments - totalExpensesWithInvestments;

  // Función para agregar una nueva transacción
  const handleAddTransaction = (transaction) => {
    setTransactions([...transactions, transaction]);
  };

  // Función para agregar una nueva inversión
  const handleAddInvestment = (investment) => {
    setInvestments([...investments, investment]);

    // Registrar el costo inicial como un gasto
    handleAddTransaction({
      description: `Compra de laptop (${investment.brand})`,
      amount: investment.initialCost,
      type: 'expense',
    });

    // Registrar el precio de venta como un ingreso
    handleAddTransaction({
      description: `Venta de laptop (${investment.brand})`,
      amount: investment.salePrice,
      type: 'income',
    });
  };

  const handleEditInvestment = (index) => {
    console.log('Editar inversión:', investments[index]);
  };

  // Definir las pestañas
  const tabs = ['Resumen', 'Transacciones', 'Inversiones'];

  return (
    <div>
      <Navbar />
      <div className={styles.dashboard}>
        <h1>Dashboard</h1>
        <Tabs tabs={tabs} activeTab={activeTab} onTabChange={setActiveTab} />

        {activeTab === 0 && (
          <div className={styles.summaryCard}>
            <SummaryCard
              totalIncome={totalIncomeWithInvestments}
              totalExpenses={totalExpensesWithInvestments}
              balance={balance}
            />
          </div>
        )}

        {activeTab === 1 && (
          <div className={styles.transactionSection}>
            <h2>Transacciones</h2>
            <TransactionForm onAddTransaction={handleAddTransaction} />
            <TransactionList transactions={transactions} />
          </div>
        )}

        {activeTab === 2 && (
          <div className={styles.investmentSection}>
            <h2>Inversiones en Laptops</h2>
            <InvestmentForm onAddInvestment={handleAddInvestment} />
            <InvestmentList
              investments={investments}
              onEditInvestment={handleEditInvestment}
            />
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;
